(()=>{
'use strict';
if(window.__gtavAdminModDownloadFilesV1)return;window.__gtavAdminModDownloadFilesV1=true;
const API='/api/mods',TOKEN_KEY='gtav-admin-token-v2',MAX=10;
const nativeFetch=window.fetch.bind(window);
let files=[{label:'Main file',url:''}],mounted=false;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cleanFiles(){return files.map((x,i)=>({label:String(x.label||'').trim()||`File ${i+1}`,url:String(x.url||'').trim()})).filter(x=>x.url).slice(0,MAX)}
function syncPrimary(){const input=$('mod-download');if(!input)return;const first=files[0]?.url||'';input.value=first;input.dispatchEvent(new Event('input',{bubbles:true}))}
function render(){const list=$('mod-download-files-list'),add=$('mod-download-file-add');if(!list)return;list.replaceChildren();files.forEach((file,index)=>{const row=document.createElement('div');row.className='mod-download-file-row';row.innerHTML=`<span class="mod-download-file-index">${String(index+1).padStart(2,'0')}</span><input class="mod-download-file-label" maxlength="80" value="${esc(file.label)}" placeholder="${index===0?'Main file':`File ${index+1}`}" aria-label="File name ${index+1}"><input class="mod-download-file-url" type="url" value="${esc(file.url)}" placeholder="https://gofile.io/d/..." aria-label="Download URL ${index+1}"><button type="button" class="mod-download-file-remove" aria-label="Remove file" ${files.length===1?'disabled':''}>×</button>`;const label=row.querySelector('.mod-download-file-label'),url=row.querySelector('.mod-download-file-url'),remove=row.querySelector('.mod-download-file-remove');label.addEventListener('input',()=>{files[index].label=label.value});url.addEventListener('input',()=>{files[index].url=url.value;if(index===0)syncPrimary()});remove.addEventListener('click',()=>{if(files.length===1)return;files.splice(index,1);render();syncPrimary()});list.append(row)});if(add)add.disabled=files.length>=MAX;syncPrimary()}
function setFiles(value){const source=Array.isArray(value)?value:[];files=source.slice(0,MAX).map((x,i)=>({label:String(x?.label||x?.title||`File ${i+1}`),url:String(x?.url||x?.downloadUrl||'')}));if(!files.length){const primary=$('mod-download')?.value||'';files=[{label:'Main file',url:primary}]}render()}
async function loadEditing(){const id=$('mod-editing-id')?.value;if(!id)return;const token=sessionStorage.getItem(TOKEN_KEY)||'';if(!token)return;try{const response=await nativeFetch(API+'?admin=1',{headers:{'X-Admin-Token':token},cache:'no-store'});if(!response.ok)return;const data=await response.json(),item=(data.mods||[]).find(x=>x.id===id);if(item)setFiles(item.downloadOptions?.length?item.downloadOptions:[{label:'Main file',url:item.downloadUrl||''}])}catch{}}
function reset(){files=[{label:'Main file',url:''}];render()}
function mount(){const input=$('mod-download');if(!input||mounted)return false;mounted=true;const field=input.closest('.field');if(!field)return false;field.classList.add('mod-download-original-field');field.hidden=true;const block=document.createElement('div');block.className='field mod-download-files-field';block.innerHTML=`<div class="mod-download-files-head"><div><label>Download files *</label><small>Add up to ${MAX} files to this mod. The first file is the primary download.</small></div><button type="button" class="mini" id="mod-download-file-add">+ Add file</button></div><div id="mod-download-files-list" class="mod-download-files-list"></div>`;field.before(block);$('mod-download-file-add').addEventListener('click',()=>{if(files.length>=MAX)return;files.push({label:`File ${files.length+1}`,url:''});render();setTimeout(()=>document.querySelector('.mod-download-file-row:last-child .mod-download-file-label')?.focus(),0)});document.addEventListener('click',event=>{if(event.target.closest('#mods-admin-list [data-edit]'))setTimeout(loadEditing,80);if(event.target.closest('#mod-reset'))setTimeout(reset,20)},true);$('mod-admin-form')?.addEventListener('reset',()=>setTimeout(reset,0));render();return true}
window.fetch=async function(input,init){try{const url=typeof input==='string'?input:input?.url||'',method=String(init?.method||'GET').toUpperCase();if(url.includes('/api/mods')&&(method==='POST'||method==='PUT')&&typeof init?.body==='string'){const body=JSON.parse(init.body),valid=cleanFiles();if(valid.length){body.downloadOptions=valid;body.downloadUrl=valid[0].url;init={...init,body:JSON.stringify(body)}}}}catch{}return nativeFetch(input,init)};
function init(){if(mount())return;const observer=new MutationObserver(()=>{if(mount())observer.disconnect()});observer.observe(document.body,{childList:true,subtree:true});setTimeout(()=>observer.disconnect(),12000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
